"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 11 (P1 v0.3, section 4): split conversations and line pools after the two-sided check.

- Conversations: deduplicated on the normalised request, then split train 300 / dev 100 / test 600 / replication 600
  (seeded; the replication set is sealed until the decision table asks for it).
- Non-flip lines (H-E door/phone that passed the check, F3 pairs, B2 side lines, R return lines): deduplicated on
  normalised text; each unique line belongs to exactly one split (train 40%, dev 10%, test 25%, replication 25%),
  and a split draws only from its own pool (repetition within a split is allowed).
- Flip lines that passed: a common set used in every split, and about 30% (at least 2 per type) held out as
  test-only phrasings for the report-only "unseen phrasing" subset (also used by the replication set). "Hello?" stays
  in the common set. Each primary cell needs >= 5 distinct passing lines, else it becomes report-only (plan section 3).
usage: python -I scripts/step0_assign_lines.py
"""
import json
import random
import re
import sys

sys.path.insert(0, "scripts")
from step0_check_batches import norm  # noqa: E402

SEED = 20261114
GEN = "data/lines_gen"
# conversation text must not hint at events or other people (generation constraint, enforced here)
BAD = re.compile(r"\b(phone|phones|call|calls|calling|ring|ringing|ringtone|door|doors|doorbell|bell|knock\w*|visitor\w*|"
                 r"deliver\w*|courier|package|parcel|neighbou?r\w*|family|wife|husband|partner|son|daughter|kids?|"
                 r"child\w*|roommate\w*|mom|dad|mother|father|brother|sister|guest\w*|someone|somebody|pause|wait|"
                 r"hold on)\b", re.I)


def split_unique(lines, rng, shares=(("train", 0.40), ("dev", 0.10), ("test", 0.25), ("replication", 0.25))):
    groups = {}                     # F3 pairs are grouped by the user's reply, so a reply text lives in one split
    for x in lines:
        groups.setdefault(norm(x if isinstance(x, str) else x["user_reply"]), []).append(x)
    keys = sorted(groups)
    rng.shuffle(keys)
    out, start = {}, 0
    for i, (name, share) in enumerate(shares):
        end = len(keys) if i == len(shares) - 1 else start + round(share * len(keys))
        out[name] = [y for k in keys[start:end] for y in (groups[k] if not isinstance(groups[k][0], str)
                                                          else groups[k][:1])]
        start = end
    return out


def main():
    rng = random.Random(SEED)
    convs = json.load(open(f"{GEN}/conversations_candidates.json", encoding="utf-8"))
    try:
        convs += json.load(open(f"{GEN}/conversations_candidates_extra.json", encoding="utf-8"))
    except FileNotFoundError:
        pass
    pools = json.load(open(f"{GEN}/pools_candidates.json", encoding="utf-8"))
    check = json.load(open("results/step0/line_check.json", encoding="utf-8"))
    n_all = len(convs)
    convs = [c for c in convs if not BAD.search(" ".join([c["user_request"], c["agent_answer"], c["user_followup"]]))]
    print(f"conversations: {n_all} generated, {n_all - len(convs)} dropped for event or person words")
    seen, uniq = set(), []
    for c in convs:
        k = norm(c["user_request"])
        if k and k not in seen:
            seen.add(k)
            uniq.append(c)
    rng.shuffle(uniq)
    sizes = (("train", 300), ("dev", 100), ("test", 600), ("replication", 600))
    if len(uniq) < sum(n for _, n in sizes):
        raise SystemExit(f"only {len(uniq)} unique conversations")
    conv_split, start = {}, 0
    for name, n in sizes:
        conv_split[name] = uniq[start:start + n]
        start += n
    fu_splits = {}
    for name, cs in conv_split.items():
        for c in cs:
            fu_splits.setdefault(norm(c["user_followup"]), set()).add(name)
    followup_blocked = sorted(k for k, s in fu_splits.items() if len(s) > 1)
    lines = {}
    for kind in ("he_door", "he_phone"):
        ok = [v["line"] for k, v in check["he"].items() if k.startswith(kind + ":") and v["pass"]]
        lines[kind] = split_unique(ok, rng)
    for kind in ("f3_pair", "b2_side", "r_line"):
        lines[kind] = split_unique([p if kind == "f3_pair" else p["text"] for p in pools[kind]], rng)
    flip = {}
    passing = {kind: sorted({v["line"] for k, v in check["flip"].items() if k.startswith(kind + ":") and v["pass"]})
               for kind in ("phone_flip", "door_flip")}
    for kind in ("phone_flip", "door_flip"):
        ok = passing[kind]
        other = {norm(x) for k2, xs in passing.items() if k2 != kind for x in xs}
        hello = [x for x in ok if norm(x) == "hello"]
        rest = [x for x in ok if norm(x) != "hello"]
        rng.shuffle(rest)
        # a test-only phrasing must not occur anywhere else (not even as the other cell's common line)
        eligible = [x for x in rest if norm(x) not in other]
        n_hold = min(len(eligible), max(2, round(0.3 * len(ok)))) if len(ok) >= 7 else 0
        hold = eligible[:n_hold]
        common = hello + [x for x in rest if x not in hold]
        flip[kind] = {"common": common, "test_only": hold, "primary_ok": len(common) >= 5}
    out = {"seed": SEED, "conversations": conv_split, "lines": lines, "flip": flip,
           "followup_blocked": followup_blocked,
           "counts": {"conversations": {k: len(v) for k, v in conv_split.items()},
                      "followup_blocked": len(followup_blocked),
                      "lines": {k: {s: len(x) for s, x in v.items()} for k, v in lines.items()},
                      "flip": {k: {"common": len(v["common"]), "test_only": len(v["test_only"]),
                                   "primary_ok": v["primary_ok"]} for k, v in flip.items()}}}
    json.dump(out, open("results/step0/line_assignment.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print(json.dumps(out["counts"], indent=1))


if __name__ == "__main__":
    main()
